Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/people.ListView */}}
{{/* Starting point generated by WebThings: every field of the data is used below. */}}
<main id="content">
    <h1>{{.Title}}</h1>
    {{range .People}}
        <article>
            {{/* ID: {{.ID}} — stable, usable as an anchor */}}
            {{with .Slug}}<p>{{.}}</p>{{end}}
            {{with .Name}}<p>{{.}}</p>{{end}}
            {{with .Group}}<p>{{.}}</p>{{end}}
            {{with .Role}}<p>{{.}}</p>{{end}}
            <div>{{.Bio}}</div>
            {{with .Email}}<p>{{.}}</p>{{end}}
            {{with .Phone}}<p>{{.}}</p>{{end}}
            {{with .PhoneURL}}<a href="{{.}}">PhoneURL</a>{{end}}
            {{with .Website}}<p>{{.}}</p>{{end}}
            {{with .LinkedIn}}<p>{{.}}</p>{{end}}
            {{if .PhotoURL}}<img src="{{.PhotoURL}}"{{with .PhotoSrcset}} srcset="{{.}}" sizes="100vw"{{end}} alt="">{{end}}
            {{/* PhotoOriginalURL: {{.PhotoOriginalURL}} — the uploaded file, for a download link */}}
            {{with .URL}}<a href="{{.}}">URL</a>{{end}}
        </article>
    {{end}}
    {{range .Groups}}
        <article>
            {{with .Name}}<p>{{.}}</p>{{end}}
            {{range .People}}
                <article>
                </article>
            {{end}}
        </article>
    {{end}}
</main>

